import { useState, type ChangeEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { PERSON_ROW_SPAN, PersonCells, PersonColumnHead, PersonDetail } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { periodOf, usePeriods } from '../periods/usePeriods';
import { rateFor, useRates } from '../rates/useRates';
import { claimDueNow, isOverdue } from '../overdue/useOverdue';
import { useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { claimed, claimsKey, isDeferred, useClaims, type Claim } from './useClaims';
import { useClaimSelection } from './useClaimSelection';

/** A person's claimed: the sum of their counted (OPEN, PENDING or SETTLED; an open one dated within a hold only when a statement binds it; not a deferred one) claims' amounts. */
function PersonClaimed({ sheetId, personId }: { sheetId: string; personId: number }) {
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  return (
    <td data-testid="person-claimed">
      {claimed((claims.data ?? []).filter((c) => c.personId === personId), holdsById(people.data), today)}
    </td>
  );
}

type ClaimAction = 'open' | 'settle' | 'approve' | 'reject' | 'void' | 'resettle' | 'defer' | 'proof';

/** A claim's status changes; the server refuses one its status does not allow, a settle by the user
 *  who opened the claim, and an approve or reject by anyone but a steward (an approve also by the
 *  user who opened the claim), and a re-settle by anyone but a steward or of a claim not SETTLED. A reject takes the reason typed on the claim's row.
 *  A settle or approve of a claim whose due is above the proof threshold in force on its date is refused while it has no proof. */
const ACTIONS: [Exclude<ClaimAction, 'defer' | 'proof'>, string][] = [
  ['open', 'Open'],
  ['settle', 'Settle'],
  ['approve', 'Approve'],
  ['reject', 'Reject'],
  ['void', 'Void'],
  ['resettle', 'Re-settle'],
];

/** A person's claims, newest first, under their row, with a form that adds a claim, or edits one
 *  when its editor is open. A blank date takes the sheet's today. A negative amount is a correction:
 *  the form names, by number, the settled claim of the same person it corrects. */
function PersonClaims({ sheetId, personId }: { sheetId: string; personId: number }) {
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId).data?.today;
  const periods = usePeriods(sheetId);
  const queryClient = useQueryClient();
  const selection = useClaimSelection(sheetId);
  const [editing, setEditing] = useState<number | null>(null);
  const [refused, setRefused] = useState<number | null>(null);
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [note, setNote] = useState('');
  const [corrects, setCorrects] = useState('');
  const [reasons, setReasons] = useState<Record<number, string>>({});
  const [targets, setTargets] = useState<Record<number, string>>({});
  const [deferDates, setDeferDates] = useState<Record<number, string>>({});

  const clearForm = () => {
    setEditing(null);
    setAmount('');
    setDate('');
    setNote('');
    setCorrects('');
  };

  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { id: number | null; amount: string; date: string; note: string; corrects: string }) => {
      const sheet = `/api/sheets/${encodeURIComponent(sheetId)}`;
      const path = f.id === null ? `${sheet}/people/${personId}/claims` : `${sheet}/claims/${f.id}`;
      return postJson<Claim>(path, { amount: f.amount, date: f.date, note: f.note, corrects: f.corrects });
    },
    onSuccess: async () => {
      clearForm();
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  // A status change (open, settle, approve, reject, void) of one claim, or deferring an OPEN one until the
  // date typed on its row, or adding a proof to it; a refusal shows on that claim's row.
  const action = useMutation({
    mutationFn: (a: { id: number; action: ClaimAction; reason: string; until: string }) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${a.id}/${a.action}`, { reason: a.reason, until: a.until }),
    onSuccess: (_, a) => {
      if (a.action === 'reject') setReasons((r) => ({ ...r, [a.id]: '' }));
      if (a.action === 'defer') setDeferDates((d) => ({ ...d, [a.id]: '' }));
    },
    onSettled: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  // A steward moves a DRAFT, OPEN or PENDING claim to the person chosen on its row; a refusal shows on that claim's row.
  const reassign = useMutation({
    mutationFn: (r: { id: number; personId: number | null }) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/reassign`, { claimId: r.id, personId: r.personId }),
    onSuccess: (_, r) => setTargets((t) => ({ ...t, [r.id]: '' })),
    onSettled: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  const move = (id: number) => {
    setRefused(null);
    action.reset();
    reassign.reset();
    const target = targets[id] ?? '';
    reassign.mutate({ id, personId: target === '' ? null : Number(target) });
  };

  const act = (id: number, a: ClaimAction) => {
    setRefused(null);
    action.reset();
    reassign.reset();
    action.mutate({
      id,
      action: a,
      reason: a === 'reject' ? reasons[id] ?? '' : '',
      until: a === 'defer' ? (deferDates[id] ?? '').trim() : '',
    });
  };

  // Only a DRAFT can be edited: editing any other claim is refused on its row and opens no editor
  // (to change an open claim, void it and add a new one).
  const openEditor = (c: Claim) => {
    save.reset();
    action.reset();
    reassign.reset();
    if (c.status !== 'DRAFT') {
      setRefused(c.id);
      return;
    }
    setRefused(null);
    setEditing(c.id);
    setAmount(c.amount);
    setDate(c.date);
    setNote(c.note);
    setCorrects(c.corrects === null ? '' : String(c.corrects));
  };

  const cancel = () => {
    save.reset();
    clearForm();
  };

  const field = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement>) => {
    set(e.target.value);
    save.reset();
  };

  const mine = (claims.data ?? []).filter((c) => c.personId === personId);
  // A claim's due: the one fixed when it was settled, else the one its last statement bound it to,
  // else its amount at the rate in force on its date for the grade its person had on that date, at least the sheet's floor
  // ('n/a' when none applies), with its late charge while it is overdue.
  const person = people.data?.find((p) => p.id === personId);

  return (
    <tr>
      <td colSpan={PERSON_ROW_SPAN}>
        <form
          data-testid="claim-form"
          onSubmit={(e) => {
            e.preventDefault();
            setRefused(null);
            submitOnce(() => {
              save.reset();
              return save.mutateAsync({ id: editing, amount, date, note, corrects });
            });
          }}
        >
          <label>
            Amount <input data-testid="claim-form-amount" inputMode="decimal" value={amount} onChange={field(setAmount)} />
          </label>{' '}
          <label>
            Date{' '}
            <input
              type="text"
              placeholder="yyyy-mm-dd"
              data-testid="claim-form-date"
              value={date}
              onChange={field(setDate)}
            />
          </label>{' '}
          <label>
            Note <input data-testid="claim-form-note" value={note} onChange={field(setNote)} />
          </label>{' '}
          <label>
            Corrects{' '}
            <input
              data-testid="claim-form-corrects"
              inputMode="numeric"
              placeholder="claim no."
              value={corrects}
              onChange={field(setCorrects)}
            />
          </label>{' '}
          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
            {editing === null ? 'Add claim' : 'Save claim'}
          </button>
          {save.isError && <p data-testid="claim-form-error">{save.error.message}</p>}
        </form>
        <table data-testid="claims-list">
          <tbody>
            {mine.map((c) => (
              <tr key={c.id} data-testid={`claim-row-${c.id}`}>
                <td>
                  <input
                    type="checkbox"
                    data-testid="claim-select"
                    checked={selection.ids.has(c.id)}
                    onChange={(e) => selection.toggle(c.id, e.target.checked)}
                  />
                </td>
                <td data-testid="claim-number">{c.number ?? ''}</td>
                <td data-testid="claim-amount">{c.amount}</td>
                <td data-testid="claim-date">{c.date}</td>
                <td data-testid="claim-period">{periodOf(periods.data, c.date)?.name ?? ''}</td>
                <td data-testid="claim-note">{c.note}</td>
                <td data-testid="claim-due">
                  {claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(person, c.date), c.date), settings, today)}
                </td>
                <td data-testid="claim-due-by">{c.dueBy}</td>
                <td data-testid="claim-overdue">
                  {today === undefined ? '' : isOverdue(c, today) ? 'yes' : 'no'}
                </td>
                <td data-testid="claim-corrects">{c.corrects ?? ''}</td>
                <td data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</td>
                <td data-testid="claim-status">{c.status}</td>
                <td data-testid="claim-opened-by">{c.openedBy ?? ''}</td>
                <td data-testid="claim-proofs">{c.proofs}</td>
                <td data-testid="claim-deferred">{isDeferred(c, today) ? 'yes' : 'no'}</td>
                <td data-testid="claim-deferred-until">{c.deferredUntil ?? ''}</td>
                <td data-testid="claim-log">
                  {c.log.map((line, i) => (
                    <div key={i} data-testid="claim-log-line">
                      {line}
                    </div>
                  ))}
                </td>
                <td>
                  <input
                    data-testid="claim-reject-reason"
                    placeholder="reject reason"
                    value={reasons[c.id] ?? ''}
                    onChange={(e) => {
                      const v = e.target.value;
                      setReasons((r) => ({ ...r, [c.id]: v }));
                    }}
                  />{' '}
                  {ACTIONS.map(([a, label]) => (
                    <button
                      key={a}
                      type="button"
                      data-testid={`claim-${a}`}
                      disabled={action.isPending}
                      onClick={() => act(c.id, a)}
                    >
                      {label}
                    </button>
                  ))}
                  <button
                    type="button"
                    data-testid="claim-proof"
                    disabled={action.isPending}
                    onClick={() => act(c.id, 'proof')}
                  >
                    Add proof
                  </button>{' '}
                  <input
                    type="text"
                    data-testid="claim-defer-date"
                    placeholder="defer until yyyy-mm-dd"
                    value={deferDates[c.id] ?? ''}
                    onChange={(e) => {
                      const v = e.target.value;
                      setDeferDates((d) => ({ ...d, [c.id]: v }));
                      if (action.variables?.id === c.id) action.reset();
                    }}
                  />{' '}
                  <button
                    type="button"
                    data-testid="claim-defer"
                    disabled={action.isPending}
                    onClick={() => act(c.id, 'defer')}
                  >
                    Defer
                  </button>{' '}
                  <select
                    data-testid="claim-reassign-to"
                    value={targets[c.id] ?? ''}
                    onChange={(e) => {
                      const v = e.target.value;
                      setTargets((t) => ({ ...t, [c.id]: v }));
                    }}
                  >
                    <option value="">move to…</option>
                    {(people.data ?? [])
                      .filter((p) => p.id !== personId)
                      .map((p) => (
                        <option key={p.id} value={String(p.id)}>
                          {p.name}
                        </option>
                      ))}
                  </select>{' '}
                  <button
                    type="button"
                    data-testid="claim-reassign"
                    disabled={reassign.isPending}
                    onClick={() => move(c.id)}
                  >
                    Reassign
                  </button>
                  {reassign.isError && reassign.variables?.id === c.id && (
                    <span data-testid="claim-error">{reassign.error.message}</span>
                  )}
                  {action.isError && action.variables?.id === c.id && (
                    <span data-testid="claim-error">{action.error.message}</span>
                  )}
                  {refused === c.id && <span data-testid="claim-error">only a DRAFT claim can be edited</span>}
                </td>
                <td>
                  {editing === c.id ? (
                    <button type="button" data-testid="claim-cancel" onClick={cancel}>
                      Cancel
                    </button>
                  ) : (
                    <button type="button" data-testid="claim-edit" onClick={() => openEditor(c)}>
                      Edit
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {claims.isError && <p data-testid="claims-error">{claims.error.message}</p>}
      </td>
    </tr>
  );
}

/** Open the selected claims together: the server opens, in list order, each that can be opened and
 *  leaves the rest; the bar shows how many were opened and how many refused (gone while it runs). */
function BulkOpen({ sheetId }: { sheetId: string }) {
  const selection = useClaimSelection(sheetId);
  const queryClient = useQueryClient();
  const submitOnce = useSingleFlight();
  const bulk = useMutation({
    mutationFn: (claimIds: number[]) =>
      postJson<{ opened: number; refused: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-open`, { claimIds }),
    onSuccess: () => selection.clear(),
    onSettled: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  return (
    <p data-testid="bulk-open-bar">
      <button
        type="button"
        data-testid="bulk-open"
        disabled={bulk.isPending}
        onClick={() =>
          submitOnce(() => {
            bulk.reset();
            return bulk.mutateAsync([...selection.ids]);
          })
        }
      >
        Open selected ({selection.ids.size})
      </button>
      {bulk.isSuccess && (
        <>
          {' '}
          Opened <strong data-testid="bulk-opened">{bulk.data.opened}</strong>, refused{' '}
          <strong data-testid="bulk-refused">{bulk.data.refused}</strong>
        </>
      )}
      {bulk.isError && <span data-testid="bulk-open-error">{bulk.error.message}</span>}
    </p>
  );
}

/** Settle the selected claims together: the server settles, in list order and by the rules of a single
 *  settle, each that can be settled (one sent to PENDING counts) and leaves the rest; the bar shows how
 *  many were settled and how many refused (gone while it runs). */
function BulkSettle({ sheetId }: { sheetId: string }) {
  const selection = useClaimSelection(sheetId);
  const queryClient = useQueryClient();
  const submitOnce = useSingleFlight();
  const bulk = useMutation({
    mutationFn: (claimIds: number[]) =>
      postJson<{ settled: number; refused: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-settle`, { claimIds }),
    onSuccess: () => selection.clear(),
    onSettled: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  return (
    <p data-testid="bulk-settle-bar">
      <button
        type="button"
        data-testid="bulk-settle"
        disabled={bulk.isPending}
        onClick={() =>
          submitOnce(() => {
            bulk.reset();
            return bulk.mutateAsync([...selection.ids]);
          })
        }
      >
        Settle selected ({selection.ids.size})
      </button>
      {bulk.isSuccess && (
        <>
          {' '}
          Settled <strong data-testid="bulk-settled">{bulk.data.settled}</strong>, refused{' '}
          <strong data-testid="bulk-settle-refused">{bulk.data.refused}</strong>
        </>
      )}
      {bulk.isError && <span data-testid="bulk-settle-error">{bulk.error.message}</span>}
    </p>
  );
}

/** The sheet's claimed-total: everyone's claimed added up. */
function ClaimedTotal({ sheetId }: { sheetId: string }) {
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  return (
    <p>
      Claimed total: <strong data-testid="rollup-claimed-total">{claimed(claims.data ?? [], holdsById(people.data), today)}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHead.fill({ order: 10, Component: () => <th>Claimed</th> }),
  PersonCells.fill({ order: 10, Component: PersonClaimed }),
  PersonDetail.fill({ order: 10, Component: PersonClaims }),
  SheetBody.fill({ order: 15, Component: BulkOpen }),
  SheetBody.fill({ order: 16, Component: BulkSettle }),
  SheetBody.fill({ order: 20, Component: ({ sheetId }) => <ClaimedTotal sheetId={sheetId} /> }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { heldOn, type Hold } from '../people/usePeople';

/** A claim's status: DRAFT -> OPEN -> SETTLED; a clerk's settle above the clerk limit goes to PENDING
 *  instead, which a steward approves (SETTLED) or rejects (OPEN again); a DRAFT, OPEN or PENDING claim
 *  can become VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A claim: its amount with two decimals, its date (yyyy-mm-dd), its note, its status, its number on
 *  the sheet (given when it is opened: 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft and once void) and the due fixed when it was
 *  settled (null unless settled while its grade had a rate: its due is then live, from the rates), and
 *  who opened it (null until it is opened), whether its person's last statement bound it, and the figure
 *  it was bound to (null when not bound, or bound with no figure: its due then stays live), and, for a
 *  correction (a negative amount), the number of the settled claim of the same person it corrects, and
 *  its due-by (yyyy-mm-dd), fixed when it was created from the terms of its person's grade then (else the
 *  sheet's terms), and its status log: a line per status it has had, oldest first, as
 *  "<STATUS> by <user> on <date> due=<due>" with the sheet's today and its due at that moment, and whether
 *  its last statement bound it to n/a (the rate that would apply to it had ended: its due stays n/a), and
 *  the date it is deferred until (null when it was never deferred: see `isDeferred`), and how many proofs it has. */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  statedNa: boolean;
  deferredUntil: string | null;
  proofs: number;
  log: string[];
};

/** Whether a claim is open: OPEN, or PENDING (handled like OPEN everywhere but its statement binding). */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** A claim's fixed figure: the due frozen when it was settled, else the one its last statement bound
 *  it to (a PENDING claim is not bound; 'n/a' when it bound it to n/a); null when its due is live. */
export function fixedDue(c: Claim): string | null {
  if (c.due !== null) return c.due;
  if (!isBound(c)) return null;
  return c.statedNa ? 'n/a' : c.statedDue;
}

/** Whether a claim is deferred now: it is OPEN and the date it is deferred until is after the sheet's
 *  today. Until today reaches that date it counts in no total, is not overdue and cannot be settled. */
export function isDeferred(c: Claim, today: string | undefined): boolean {
  return c.status === 'OPEN' && c.deferredUntil !== null && today !== undefined && today < c.deferredUntil;
}

/** Whether a claim counts toward claimed and every live total, given the people's holds by person id
 *  and the sheet's today: only open (OPEN or PENDING) and SETTLED claims do, and an open claim dated within
 *  one of its person's holds does not, unless a statement binds it, nor does a deferred one. */
export function counts(c: Claim, holds: ReadonlyMap<number, Hold[]>, today: string | undefined): boolean {
  return c.status === 'SETTLED'
    || (isOpen(c) && !isDeferred(c, today) && (isBound(c) || !heldOn(holds.get(c.personId), c.date)));
}

/** A claim's status at the end of a day (yyyy-mm-dd), as its status log records it: the last line dated
 *  on or before it; null when the claim did not yet exist then. */
export function statusOn(c: Claim, day: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of c.log) {
    const m = /^(\w+) by .* on (\d{4}-\d{2}-\d{2}) due=/.exec(line);
    if (m && m[2] <= day) status = m[1] as ClaimStatus;
  }
  return status;
}

/** Whether a claim counts toward a period ending on a day: by the live rules (holds, deferral, binding),
 *  applied to the status it had at the end of that day; not when it did not yet exist then. A hold leaves
 *  out only a claim still open now: one since settled or voided counts by the status it had then. */
export function countsOn(c: Claim, day: string, holds: ReadonlyMap<number, Hold[]>, today: string | undefined): boolean {
  const status = statusOn(c, day);
  return status !== null && counts({ ...c, status }, isOpen(c) ? holds : new Map(), today);
}

/** Whether its person's last statement binds a claim now: it was stated and is not PENDING. */
export function isBound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

export function claimsKey(sheetId: string) {
  return ['sheet', sheetId, 'claims'];
}

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: async () => {
      const res = await getJson<{ claims: Omit<Claim, 'log'>[]; logs: Record<string, string[]> }>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims`,
      );
      return res.claims.map((c): Claim => ({ ...c, log: res.logs[String(c.id)] ?? [] }));
    },
  });
}

/** The sum of the amounts of those of these claims that count (given the people's holds by person id and
 *  the sheet's today), with two decimals (added up in cents, so no rounding drift). */
export function claimed(claims: Claim[], holds: ReadonlyMap<number, Hold[]>, today: string | undefined): string {
  const cents = claims.filter((c) => counts(c, holds, today)).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

